import {createReadStream,createWriteStream} from 'node:fs';
import {stat,mkdir,rename,rm} from 'node:fs/promises';
import {extname,join,basename} from 'node:path';
import {randomUUID} from 'node:crypto';
import {pipeline} from 'node:stream/promises';
import {cachedSong,importLocalSong,localExtensions} from './providers.mjs';
const types={'.mp3':'audio/mpeg','.wav':'audio/wav','.flac':'audio/flac','.m4a':'audio/mp4','.aac':'audio/aac','.ogg':'audio/ogg','.opus':'audio/ogg','.mp4':'video/mp4','.webm':'video/webm','.aiff':'audio/aiff','.aif':'audio/aiff','.wma':'audio/x-ms-wma'};
export function byteRange(value,size){if(!value)return {start:0,end:size-1,partial:false};const match=/^bytes=(\d*)-(\d*)$/.exec(value);if(!match||(!match[1]&&!match[2]))return null;const start=match[1]?Number(match[1]):Math.max(0,size-Number(match[2])),end=match[1]?(match[2]?Math.min(Number(match[2]),size-1):size-1):size-1;if(!Number.isSafeInteger(start)||!Number.isSafeInteger(end)||start<0||start>=size||end<start)return null;return {start,end,partial:true};}
export async function serveLocal(req,res,key){const song=cachedSong(key);if(song.source!=='local'||!song.localPath)throw Error('未导入此本地音源');const file=await stat(song.localPath);if(!file.size&&!req.headers.range){res.writeHead(200,{'Content-Length':0});return res.end();}const range=byteRange(req.headers.range,file.size);if(!range){res.writeHead(416,{'Content-Range':`bytes */${file.size}`});return res.end();}res.writeHead(range.partial?206:200,{'Content-Type':types[extname(song.localPath).toLowerCase()]||'application/octet-stream','Content-Length':range.end-range.start+1,'Accept-Ranges':'bytes','Cache-Control':'no-store','Referrer-Policy':'no-referrer',...(range.partial?{'Content-Range':`bytes ${range.start}-${range.end}/${file.size}`}:{})});if(req.method==='HEAD')return res.end();await pipeline(createReadStream(song.localPath,{start:range.start,end:range.end}),res);}
export async function uploadLocal(req,root,name){const extension=extname(name).toLowerCase();if(!localExtensions.has(extension))throw Error('请选择音频文件或MP4/WebM音轨');const dir=join(root,'local-media');await mkdir(dir,{recursive:true});const path=join(dir,randomUUID()+extension),partial=path+'.part';try{await pipeline(req,createWriteStream(partial));await rename(partial,path);return await importLocalSong({path,name:basename(name,extname(name))});}catch(e){await rm(partial,{force:true});throw e;}}
